    private void await(BooleanSupplier condition,String message)throws Exception{long end=SystemClock.elapsedRealtime()+7000;boolean passed;while(!(passed=condition.getAsBoolean())&&SystemClock.elapsedRealtime()<end)Thread.sleep(70);check.accept(passed,message);}
    private void shell(String command)throws Exception{try(ParcelFileDescriptor fd=i.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){in.readAllBytes();}}
    private static TextView text(View view,String value){if(view instanceof TextView t&&value.contentEquals(t.getText()))return t;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){TextView found=text(group.getChildAt(n),value);if(found!=null)return found;}return null;}
    private PlaybackState playback(boolean playing,long position,long actions){return new PlaybackState.Builder().setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position,playing?1:0,SystemClock.elapsedRealtime()).setActions(actions).setActiveQueueItemId(queued.get()>0?queued.get():11).addCustomAction(new PlaybackState.CustomAction.Builder("favorite",favorites.get()>0?"Saved":"Favorite",com.nook.widgets.R.drawable.ic_music_note).build()).build();}
    private MediaMetadata metadata(String title){return new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,"Paper Satellites · generated test artist").putString(MediaMetadata.METADATA_KEY_ALBUM,"Night Drive · sample album").putLong(MediaMetadata.METADATA_KEY_DURATION,210000).putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,art).build();}
