    private static ScrollView findScroll(View root){if(root instanceof ScrollView scroll)return scroll;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){ScrollView found=findScroll(group.getChildAt(n));if(found!=null)return found;}return null;}
    private void shot(String name)throws Exception{Bitmap screenshot=i.getUiAutomation().takeScreenshot();File folder=new File(c.getFilesDir(),"screenshots");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();}
    private interface GestureStep{void run()throws Exception;}
    private void drag(SeekBar bar,float fraction)throws Exception{drag(bar,fraction,null);}
    private void drag(SeekBar bar,float fraction,GestureStep during)throws Exception{main(()->bar.requestRectangleOnScreen(new Rect(0,0,bar.getWidth(),bar.getHeight()),true));int[] at=new int[2];main(()->bar.getLocationOnScreen(at));float available=bar.getWidth()-bar.getPaddingLeft()-bar.getPaddingRight(),start=at[0]+bar.getPaddingLeft()+available*bar.getProgress()/Math.max(1,bar.getMax()),x=at[0]+bar.getPaddingLeft()+available*fraction,y=at[1]+bar.getHeight()/2f;long now=SystemClock.uptimeMillis();i.sendPointerSync(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,start,y,0));i.sendPointerSync(MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_MOVE,x,y,0));if(during!=null)during.run();i.sendPointerSync(MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y,0));i.waitForIdleSync();}
    private void board(){main(()->{Bitmap sheet=Bitmap.createBitmap(1600,1700,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sheet);canvas.drawColor(Ui.BG);Paint paint=new Paint(3);paint.setColor(Ui.TEXT);paint.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));paint.setTextSize(30);canvas.drawText("Nook music · native Android layouts",24,40,paint);int[] designs={0,1,2,4,7};String[] names={"Original","Nothing-inspired","Apple-inspired","Pixel-inspired","Samsung-inspired"};for(int row=0;row<designs.length;row++)for(int variant=0;variant<4;variant++)try{JSONObject config=Widgets.defaults("music");WidgetDesign.select(config,designs[row]);config.put("variant",variant);int height=variant==1?100:250;View view=render(config,320,height);FrameLayout frame=new FrameLayout(c);if(config.optInt("style",0)!=0)frame.setBackgroundResource(com.nook.widgets.R.drawable.preview_wallpaper);frame.addView(view,new FrameLayout.LayoutParams(-1,-1));frame.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,320),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,height),View.MeasureSpec.EXACTLY));frame.layout(0,0,frame.getMeasuredWidth(),frame.getMeasuredHeight());int left=16+variant*400,top=70+row*320;paint.setTextSize(17);paint.setColor(Ui.TEXT);canvas.drawText(names[row]+" · "+MusicWidgets.variants()[variant],left,top,paint);canvas.save();canvas.translate(left,top+20+(variant==1?75:0));canvas.scale(368f/frame.getWidth(),(variant==1?115:287)/ (float)frame.getHeight());frame.draw(canvas);canvas.restore();}catch(Exception e){throw new RuntimeException(e);}paint.setTextSize(18);canvas.drawText("Generated artwork and sample MediaSession metadata · 4 layouts, 8 design languages, independent player selection",24,1680,paint);File folder=new File(c.getFilesDir(),"screenshots");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,"music-layouts.png"))){sheet.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new RuntimeException(e);}sheet.recycle();});}
