            main(()->{art=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(art);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,320,320,new int[]{0xff18254d,0xffb74e71,0xfff1b879},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,320,320,p);p.setShader(null);p.setColor(0xffead1a6);canvas.drawCircle(212,104,55,p);p.setColor(0xff1b2850);for(int n=0;n<9;n++)canvas.drawRect(20+n*35,225-n%3*12,40+n*35,320,p);session=new MediaSession(c,"Nook generated music proof");session.setCallback(new MediaSession.Callback(){public void onPause(){pauses.incrementAndGet();session.setPlaybackState(playback(false,43000,ACTIONS));}public void onPlay(){plays.incrementAndGet();session.setPlaybackState(playback(true,43000,ACTIONS));}public void onSkipToNext(){nexts.incrementAndGet();session.setMetadata(metadata("Next sample track"));}public void onSkipToPrevious(){previous.incrementAndGet();session.setMetadata(metadata("Sample track"));}public void onSeekTo(long position){seeks.set(position);session.setPlaybackState(playback(false,position,ACTIONS));}public void onSkipToQueueItem(long queue){queued.set(queue);session.setMetadata(metadata("Sample chapter two"));session.setPlaybackState(playback(false,0,ACTIONS));}public void onCustomAction(String action,Bundle extras){if(action.equals("favorite")){favorites.incrementAndGet();session.setPlaybackState(playback(false,43000,ACTIONS));}}},new Handler(Looper.getMainLooper()));session.setMetadata(metadata("Sample track"));session.setPlaybackState(playback(true,43000,ACTIONS));session.setQueue(List.of(new MediaSession.QueueItem(new MediaDescription.Builder().setTitle("Sample chapter one").build(),11),new MediaSession.QueueItem(new MediaDescription.Builder().setTitle("Sample chapter two").build(),22)));session.setPlaybackToRemote(new VolumeProvider(VolumeProvider.VOLUME_CONTROL_ABSOLUTE,10,4){@Override public void onSetVolumeTo(int value){volumes.set(value);setCurrentVolume(value);}});session.setActive(true);});await(()->MediaAccess.controller(c)!=null,"A real playing session is discoverable");
