            board();
            id=host.allocateAppWidgetId();check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,Widgets.Music.class)),"Music binds through Android's widget host");JSONObject config=Widgets.defaults("music");WidgetDesign.select(config,4);Store.config(c,id,config);Widgets.update(c,id,"music");AtomicReference<AppWidgetHostView> hostView=new AtomicReference<>();main(()->{host.startListening();AppWidgetHostView view=host.createView(c,id,AppWidgetManager.getInstance(c).getAppWidgetInfo(id));FrameLayout stage=new FrameLayout(display);stage.setBackgroundColor(Ui.BG);stage.addView(view,new FrameLayout.LayoutParams(Ui.dp(c,340),Ui.dp(c,280),Gravity.CENTER));display.setContentView(stage);hostView.set(view);});
            Chronometer clock=hostView.get().findViewById(com.nook.widgets.R.id.music_elapsed);String initial=clock.getText().toString();Thread.sleep(1300);check.accept(!initial.equals(clock.getText().toString()),"Native elapsed time advances without a widget refresh loop");shot("music-widget");main(()->hostView.get().findViewById(com.nook.widgets.R.id.widget_action1).performClick());await(()->pauses.get()==1,"Widget Pause reaches the displayed player's real callback");await(()->hostView.get().findViewById(com.nook.widgets.R.id.widget_action1).getContentDescription().toString().equals("Play"),"Playback callback refreshes the widget's play icon");main(()->hostView.get().findViewById(com.nook.widgets.R.id.widget_action1).performClick());await(()->plays.get()==1,"Widget Play resumes the real media session");main(()->hostView.get().findViewById(com.nook.widgets.R.id.widget_action2).performClick());await(()->nexts.get()==1,"Widget Next reaches the displayed player");await(()->text(hostView.get(),"Next sample track")!=null,"Track changes refresh visible title and artwork");main(()->hostView.get().findViewById(com.nook.widgets.R.id.widget_action0).performClick());await(()->previous.get()==1,"Widget Previous reaches the displayed player");
            AtomicReference<View> old=new AtomicReference<>();main(()->{session.setPlaybackState(playback(true,43000,ACTIONS));old.set(render(config,320,250));});AtomicInteger wrong=new AtomicInteger();main(()->{other=new MediaSession(c,"Other generated player");other.setCallback(new MediaSession.Callback(){public void onPause(){wrong.incrementAndGet();}},new Handler(Looper.getMainLooper()));other.setMetadata(metadata("Other sample track"));other.setPlaybackState(playback(true,0,ACTIONS));other.setActive(true);});await(()->MediaAccess.controller(c).getSessionToken().equals(other.getSessionToken()),"Automatic selection follows the more recent playing session");int before=pauses.get();main(()->old.get().findViewById(com.nook.widgets.R.id.widget_action1).performClick());await(()->pauses.get()==before+1,"An older widget action remains bound to its displayed session");check.accept(wrong.get()==0,"Transport never pauses a different active player");main(()->{other.release();other=null;});
            detail=i.startActivitySync(new Intent(c,NowPlayingActivity.class).putExtra("widget",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();check.accept(detail.findViewById(com.nook.widgets.R.id.music_seek).isEnabled(),"Now Playing enables real seeking when supported");AtomicInteger wrongSeek=new AtomicInteger();drag(detail.findViewById(com.nook.widgets.R.id.music_seek),.72f,()->{main(()->{other=new MediaSession(c,"Gesture race test player");other.setCallback(new MediaSession.Callback(){public void onSeekTo(long position){wrongSeek.incrementAndGet();}},new Handler(Looper.getMainLooper()));other.setMetadata(metadata("Gesture race track"));other.setPlaybackState(playback(true,0,ACTIONS));other.setActive(true);});await(()->MediaAccess.controller(c).getSessionToken().equals(other.getSessionToken()),"Another session can become active during a seek gesture");Thread.sleep(300);i.waitForIdleSync();});await(()->seeks.get()>140000&&seeks.get()<165000,"A real seek gesture stays with the displayed player");check.accept(wrongSeek.get()==0,"An in-progress seek never moves another player's track");main(()->{other.release();other=null;});await(()->text(detail.getWindow().getDecorView(),"Sample track")!=null,"The expanded player returns after the gesture's competing session ends");drag(detail.findViewById(com.nook.widgets.R.id.music_volume),.8f);await(()->volumes.get()>=7,"A real volume gesture reaches the session's volume provider");main(()->session.setPlaybackToRemote(new VolumeProvider(VolumeProvider.VOLUME_CONTROL_RELATIVE,10,4){}));await(()->!detail.findViewById(com.nook.widgets.R.id.music_volume).isEnabled(),"Relative-only outputs do not expose an unsupported absolute slider");check.accept(text(detail.getWindow().getDecorView(),"VOLUME · USE THE MUSIC APP")!=null,"Unsupported volume outputs explain where to adjust volume");main(()->session.setPlaybackToRemote(new VolumeProvider(VolumeProvider.VOLUME_CONTROL_ABSOLUTE,10,8){public void onSetVolumeTo(int value){volumes.set(value);setCurrentVolume(value);}}));await(()->detail.findViewById(com.nook.widgets.R.id.music_volume).isEnabled(),"Absolute volume controls return when the output supports them");main(()->detail.findViewById(com.nook.widgets.R.id.music_queue).performClick());UiAutomation automation=i.getUiAutomation();await(()->{android.view.accessibility.AccessibilityNodeInfo tree=automation.getRootInActiveWindow();return tree!=null&&!tree.findAccessibilityNodeInfosByText("Sample chapter two").isEmpty();},"Native player queue dialog becomes visible");
            // Select the native dialog row through accessibility, as a user would.
            AtomicInteger wrongQueue=new AtomicInteger();main(()->{other=new MediaSession(c,"Queue race test player");other.setCallback(new MediaSession.Callback(){public void onSkipToQueueItem(long value){wrongQueue.incrementAndGet();}},new Handler(Looper.getMainLooper()));other.setMetadata(metadata("Other queue test track"));other.setQueue(List.of(new MediaSession.QueueItem(new MediaDescription.Builder().setTitle("Other player item").build(),22)));other.setPlaybackState(playback(true,0,ACTIONS));other.setActive(true);});await(()->MediaAccess.controller(c).getSessionToken().equals(other.getSessionToken()),"Another player can become active while a queue dialog is open");
            android.view.accessibility.AccessibilityNodeInfo root=automation.getRootInActiveWindow();List<android.view.accessibility.AccessibilityNodeInfo> rows=root.findAccessibilityNodeInfosByText("Sample chapter two");check.accept(!rows.isEmpty(),"The shared player queue is visible");android.view.accessibility.AccessibilityNodeInfo row=rows.get(0);while(row!=null&&!row.isClickable())row=row.getParent();check.accept(row!=null&&row.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"A native queue item can be selected");await(()->queued.get()==22,"Queue selection reaches the displayed player's exact queue ID");check.accept(wrongQueue.get()==0,"An open queue never jumps a different player's matching queue ID");main(()->{other.release();other=null;});await(()->text(detail.getWindow().getDecorView(),"Sample chapter two")!=null,"The expanded player follows the surviving session");main(()->{TextView button=text(detail.getWindow().getDecorView(),"Favorite");if(button!=null)button.requestRectangleOnScreen(new Rect(0,0,button.getWidth(),button.getHeight()),true);check.accept(button!=null,"Player-provided custom action is visible");button.performClick();});await(()->favorites.get()==1,"Custom actions reach the actual player");await(()->text(detail.getWindow().getDecorView(),"Saved")!=null,"Custom-action labels refresh from the player's updated state");main(()->{View decor=detail.getWindow().getDecorView();ScrollView scroll=findScroll(decor);if(scroll!=null){scroll.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);scroll.clearFocus();scroll.scrollTo(0,0);}});shot("music-now-playing");
            main(()->{session.setPlaybackState(playback(false,43000,PlaybackState.ACTION_PLAY));});await(()->!detail.findViewById(com.nook.widgets.R.id.music_seek).isEnabled(),"Seeking disables when the player withdraws support");main(()->{View view=render(config,320,250);check.accept(!view.findViewById(com.nook.widgets.R.id.widget_action2).isEnabled(),"Unsupported skip controls are disabled");});
            JSONObject hub=Widgets.defaults("universal");hub.put("page","music");UniversalWidget.pageSettings(hub,"music").put("musicHideText",true);main(()->{View view=Widgets.render(c,-1,"universal",hub,false,true).apply(c,new FrameLayout(c));check.accept(view.findViewById(com.nook.widgets.R.id.widget_settings).getVisibility()==View.GONE,"Universal has no duplicate music settings button");check.accept(view.findViewById(com.nook.widgets.R.id.hub_label).getVisibility()==View.GONE&&((TextView)view.findViewById(com.nook.widgets.R.id.hub_count)).getText().length()==0,"Music hide-text also removes Universal captions");});
